import { useState } from 'react';
import { Badge, Button, Card, Toggle, ToggleGroup, cn, type BadgeTone } from '@gntik-ai/ui';
import { Check, Sparkles } from '@gntik-ai/icons';
import { formatDate, formatMoney, type DateInput } from '../format';
import { samplePlan } from './fixtures';
import { PlanSummary, type PlanSummaryProps } from './PlanSummary';
export type { SummaryPlan, PlanSummaryProps } from './PlanSummary';

export type PlanStatus = 'active' | 'trialing' | 'past_due' | 'canceled';
export type BillingCycle = 'monthly' | 'annual';

export interface BillingPlan {
  name: string;
  status?: PlanStatus;
  /** Price per month on the monthly cycle. */
  priceMonthly: number;
  /** Price per month when billed annually. Enables the monthly/annual toggle. */
  priceAnnual?: number;
  /** ISO 4217 code. Default USD. */
  currency?: string;
  /** Next renewal date. */
  renewsOn: DateInput;
  /** Short line after the renewal date, e.g. "50 seats · 2 regions". */
  summary?: string;
  features?: string[];
}

export interface BillingPlanCardProps {
  variant?: 'billing';
  plan?: BillingPlan;
  /** Initial cycle shown (uncontrolled). */
  defaultCycle?: BillingCycle;
  onCycleChange?: (cycle: BillingCycle) => void;
  onUpgrade?: () => void;
  onManage?: () => void;
  upgradeLabel?: string;
  manageLabel?: string;
  /** Heading level of the title, to fit the page outline (default h3). */
  titleAs?: 'h2' | 'h3' | 'h4';
  className?: string;
}

export type PlanCardProps = BillingPlanCardProps | PlanSummaryProps;

/** Default billing header, or an opt-in summary without sample data. */
export function PlanCard(props: PlanCardProps) {
  return props.variant === 'summary' ? <PlanSummary {...props} /> : <BillingPlanCard {...props} />;
}

const STATUS: Record<PlanStatus, { label: string; tone: BadgeTone }> = {
  active: { label: 'Active', tone: 'success' },
  trialing: { label: 'Trial', tone: 'info' },
  past_due: { label: 'Past due', tone: 'warning' },
  canceled: { label: 'Canceled', tone: 'neutral' },
};

/** Billing page header: the current plan, its price per cycle, renewal date, features and actions. */
function BillingPlanCard({
  plan = samplePlan,
  defaultCycle = 'monthly',
  onCycleChange,
  onUpgrade,
  onManage,
  upgradeLabel = 'Upgrade plan',
  manageLabel = 'Manage',
  titleAs: TitleTag = 'h3',
  className,
}: BillingPlanCardProps) {
  const [cycle, setCycle] = useState<BillingCycle>(defaultCycle);
  const hasAnnual = plan.priceAnnual != null;
  const annual = hasAnnual && cycle === 'annual';
  const perMonth = annual ? (plan.priceAnnual ?? plan.priceMonthly) : plan.priceMonthly;
  const currency = plan.currency ?? 'USD';
  const savings = hasAnnual ? Math.round((1 - (plan.priceAnnual ?? 0) / plan.priceMonthly) * 100) : 0;
  const status = STATUS[plan.status ?? 'active'];

  const changeCycle = (value: string[]) => {
    const next = value[0];
    if (next !== 'monthly' && next !== 'annual') return;
    setCycle(next);
    onCycleChange?.(next);
  };

  return (
    <Card className={cn('p-6', className)}>
      <div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <TitleTag className="text-[17px] font-semibold tracking-tight text-foreground">{plan.name} plan</TitleTag>
            <Badge tone={status.tone} dot>
              {status.label}
            </Badge>
          </div>
          <p className="mt-1 text-[13px] text-muted-foreground">
            Renews {formatDate(plan.renewsOn)}
            {plan.summary && <> · {plan.summary}</>}
          </p>
          <p className="mt-4 flex items-baseline gap-1.5">
            <span className="text-[30px] font-semibold tracking-tight text-foreground tabular-nums">
              {formatMoney(perMonth, currency, true)}
            </span>
            <span className="text-[13px] text-muted-foreground">/ month</span>
          </p>
          <p className="mt-1 text-[12px] text-muted-foreground">
            {annual ? `Billed annually (${formatMoney(perMonth * 12, currency, true)})` : 'Billed monthly'}
          </p>
        </div>
        <div className="flex flex-col items-start gap-3 sm:items-end">
          {hasAnnual && (
            <ToggleGroup size="sm" aria-label="Billing cycle" value={[cycle]} onValueChange={changeCycle}>
              <Toggle value="monthly">Monthly</Toggle>
              <Toggle value="annual">Annual{savings > 0 && ` −${savings}%`}</Toggle>
            </ToggleGroup>
          )}
          <div className="flex flex-wrap items-center gap-2">
            <Button variant="secondary" onClick={onManage}>
              {manageLabel}
            </Button>
            <Button icon={Sparkles} onClick={onUpgrade}>
              {upgradeLabel}
            </Button>
          </div>
        </div>
      </div>
      {plan.features && plan.features.length > 0 && (
        <ul aria-label={`${plan.name} plan features`} className="mt-5 grid gap-x-6 gap-y-2 border-t border-border pt-5 sm:grid-cols-2">
          {plan.features.map((f) => (
            <li key={f} className="flex items-start gap-2 text-[13px] text-foreground">
              <Check size={15} aria-hidden className="mt-0.5 shrink-0 text-primary-text" />
              {f}
            </li>
          ))}
        </ul>
      )}
    </Card>
  );
}

import {
  Badge,
  Card,
  Toggle,
  ToggleGroup,
  cn,
  type BadgeTone,
} from "@gntik-ai/ui";
import { useEffect, useState, type ReactNode } from "react";
import { formatDate, formatMoney, type DateInput } from "../format";
import type { BillingCycle } from "./PlanCard";

/** Consumer data only: each summary region is optional. Prices are cycle totals. */
export interface SummaryPlan {
  name?: string;
  statusLabel?: string;
  statusTone?: BadgeTone;
  priceMonthly?: number;
  priceAnnual?: number;
  currency?: string;
  cycle?: BillingCycle;
  renewsOn?: DateInput;
  features?: string[];
}

export interface PlanSummaryProps {
  variant: "summary";
  plan?: SummaryPlan;
  emptyLabel?: string;
  /** Consumer-supplied kit Buttons or native links. No built-in actions. */
  actions?: ReactNode;
  defaultCycle?: BillingCycle;
  onCycleChange?: (cycle: BillingCycle) => void;
  titleAs?: "h2" | "h3" | "h4";
  className?: string;
}

export function PlanSummary({
  plan,
  emptyLabel,
  actions,
  defaultCycle = "monthly",
  onCycleChange,
  titleAs: TitleTag = "h3",
  className,
}: PlanSummaryProps) {
  const title = plan?.name || emptyLabel;
  const [cycle, setCycle] = useState<BillingCycle>(defaultCycle);
  const hasBothPrices = plan?.priceMonthly != null && plan?.priceAnnual != null;
  const price = hasBothPrices
    ? cycle === "annual"
      ? plan.priceAnnual
      : plan.priceMonthly
    : (plan?.priceMonthly ?? plan?.priceAnnual);
  const changeCycle = (values: string[]) => {
    const next = values[0];
    if (next !== "monthly" && next !== "annual") return;
    setCycle(next);
    onCycleChange?.(next);
  };
  useEffect(() => {
    if (!title && process.env.NODE_ENV === "development") {
      console.warn("PlanCard summary: supply a plan name or emptyLabel.");
    }
  }, [title]);
  return (
    <Card className={cn("p-6", className)}>
      <div className="flex flex-wrap items-center gap-2">
        {title && (
          <TitleTag className="text-lg font-semibold text-foreground">
            {title}
          </TitleTag>
        )}
        {plan?.statusLabel && (
          <Badge tone={plan.statusTone ?? "neutral"} dot>
            {plan.statusLabel}
          </Badge>
        )}
      </div>
      {plan?.renewsOn != null && (
        <p className="mt-1 text-sm text-muted-foreground">
          Renews {formatDate(plan.renewsOn)}
        </p>
      )}
      {price != null && (
        <p className="mt-4 text-3xl font-semibold text-foreground tabular-nums">
          {formatMoney(price, plan?.currency, true)}
        </p>
      )}
      {plan?.cycle && (
        <p className="mt-1 text-sm text-muted-foreground">
          {(hasBothPrices ? cycle : plan.cycle) === "annual"
            ? "Billed annually"
            : "Billed monthly"}
        </p>
      )}
      {hasBothPrices && (
        <ToggleGroup
          className="mt-4"
          size="sm"
          aria-label="Billing cycle"
          value={[cycle]}
          onValueChange={changeCycle}
        >
          <Toggle value="monthly">Monthly</Toggle>
          <Toggle value="annual">Annual</Toggle>
        </ToggleGroup>
      )}
      {plan?.features && plan.features.length > 0 && (
        <ul
          aria-label="Plan features"
          className="mt-5 grid gap-2 border-t border-border pt-5 text-sm text-foreground sm:grid-cols-2"
        >
          {plan.features.map((feature) => (
            <li key={feature}>{feature}</li>
          ))}
        </ul>
      )}
      {actions && (
        <div className="mt-4 flex flex-wrap items-center gap-2">{actions}</div>
      )}
    </Card>
  );
}

import type { BillingPlan } from './PlanCard';

/** Sample current plan (neutral workspace data). */
export const samplePlan: BillingPlan = {
  name: 'Scale',
  status: 'active',
  priceMonthly: 1200,
  priceAnnual: 1000,
  currency: 'USD',
  renewsOn: '2026-06-01',
  summary: '50 seats · 2 regions',
  features: ['500,000 requests / month', '120M tokens / month', '20 GB storage', 'Audit log and SSO', 'Email support · 1 business day'],
};

/** Shared formatting for the billing blocks (en-US, Intl). */

/** A calendar date: a `Date` or an ISO `YYYY-MM-DD` string (read as a local date, no UTC shift). */
export type DateInput = Date | string;

export function toDate(value: DateInput): Date {
  if (value instanceof Date) return value;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(value);
}

const dateFmt = new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
const shortDateFmt = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

/** "June 1, 2026". */
export function formatDate(value: DateInput): string {
  return dateFmt.format(toDate(value));
}

/** "Jun 1, 2026". */
export function formatShortDate(value: DateInput): string {
  return shortDateFmt.format(toDate(value));
}

/** Money with the currency symbol: "$1,620.00" (or no decimals with `whole`). */
export function formatMoney(amount: number, currency = 'USD', whole = false): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: whole ? 0 : 2,
    maximumFractionDigits: whole ? 0 : 2,
  }).format(amount);
}

/** Grouped number, compact above a million: "412,800", "78.4M". */
export function formatQuantity(value: number): string {
  if (Math.abs(value) >= 1_000_000) {
    return new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value);
  }
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(value);
}
